const CACHE = "site-" + VERSION;
const base = new URL("./", self.location).href;

self.addEventListener("install", () => self.skipWaiting());

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("message", (event) => {
  if (event.data !== "precache-all") return;
  event.waitUntil(
    caches.open(CACHE).then(async (cache) => {
      for (const path of PRECACHE) {
        const url = new URL(path, base).href;
        if (await cache.match(url)) continue;
        try {
          const res = await fetch(url);
          if (res.ok) await cache.put(url, res);
        } catch (e) {
          // Offline right now — the next page load tries again.
        }
      }
    }),
  );
});

// <audio> asks for byte ranges; slice them out of the cached full file.
async function rangeResponse(res, range) {
  const buf = await res.arrayBuffer();
  const m = /bytes=(\d*)-(\d*)/.exec(range);
  const start = m && m[1] ? Number(m[1]) : 0;
  const end = m && m[2] ? Math.min(Number(m[2]), buf.byteLength - 1) : buf.byteLength - 1;
  return new Response(buf.slice(start, end + 1), {
    status: 206,
    headers: {
      "Content-Type": res.headers.get("Content-Type") || "application/octet-stream",
      "Content-Range": `bytes ${start}-${end}/${buf.byteLength}`,
      "Content-Length": String(end - start + 1),
    },
  });
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET" || !req.url.startsWith(base)) return;

  const key = req.url.split("#")[0].split("?")[0];
  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      const cached = await cache.match(key);
      const refresh = fetch(key)
        .then((res) => {
          if (res.ok) cache.put(key, res.clone());
          return res;
        })
        .catch(() => null);

      if (cached) {
        event.waitUntil(refresh);
        const range = req.headers.get("range");
        return range ? rangeResponse(cached, range) : cached;
      }
      if (req.headers.get("range")) {
        // Let the browser stream media normally the first time.
        event.waitUntil(refresh);
        return fetch(req);
      }
      return (await refresh) || Response.error();
    }),
  );
});
